INSERT INTO tb_worklog (worklog_id, author_id, team_id, title, request_content, work_content, status_code, importance_code, actual_hours, instruction_date, due_date, completion_date, ai_summary, ai_summary_edited, ai_processing_status, is_deleted, created_at, updated_at) VALUES
  (2001, 201, 201, '[API] AI 작성 보조 설정 등록 복구', '놓치지 않게 API 처리 흐름을 살펴보고 요청 파라미터와 응답 형태에 문제가 없는지 정리해 달라는 요청을 받았다.', 'AI 작성 보조 설정 등록 복구 작업을 진행하며 API 처리 흐름의 입력, 처리, 결과가 한 흐름으로 이어지게 조정했다. 요청 파라미터와 응답 형태를 확인한 뒤 QA에서 다시 볼 항목만 따로 남겼다.', 'COMPLETED', 'HIGH', 1.0, '2026-05-18', '2026-05-19', '2026-05-18', 'AI 작성 보조 설정 등록 복구는 API 처리 흐름의 요청 파라미터와 응답 형태를 다시 맞춘 작업이다. 입력부터 결과까지 이어지는 흐름을 정리했고, QA에서 확인할 항목만 남긴 상태로 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:00:00', '2026-05-18 18:00:00'),
  (2002, 202, 201, '[API] 태그 병합 적용 API 추가', 'TagMergeCandidateController 컨트롤러 변경 후 사용자가 겪는 흐름이 자연스러운지 확인하고 필요한 후속 조치를 적어 달라는 요청이 있었다.', 'TagMergeCandidateController 컨트롤러에서 태그 병합 적용 API 추가에 필요한 추가 작업을 처리하고, 요청과 응답이 같은 흐름으로 처리되도록 흐름을 맞췄다. 요청 파라미터와 응답 형태를 다시 확인했고, 재현 관련 남은 문제는 따로 발견되지 않았다.', 'COMPLETED', 'NORMAL', 1.5, '2026-05-18', '2026-05-19', '2026-05-18', '태그 병합 적용 API 추가는 TagMergeCandidateController 변경 이후 사용자 흐름을 자연스럽게 연결한 작업이다. 요청과 응답 처리 흐름을 맞췄고 재현 관련 잔여 문제 없이 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:11:00', '2026-05-18 18:11:00'),
  (2003, 203, 201, '[API] 태그 병합 적용 검증 추가', '눌러 보며 TagMergeCandidateServiceTest 서비스 로직을 살펴보고 요청 파라미터와 응답 형태에 문제가 없는지 정리해 달라는 요청을 받았다.', '태그 병합 적용 검증 추가 작업을 진행하며 TagMergeCandidateServiceTest 서비스 로직의 입력, 처리, 결과가 한 흐름으로 이어지게 조정했다. 요청 파라미터와 응답 형태를 다시 확인했고, 동선 관련 남은 문제는 따로 발견되지 않았다.', 'COMPLETED', 'NORMAL', 2.0, '2026-05-18', '2026-05-19', '2026-05-18', '태그 병합 적용 검증 추가는 TagMergeCandidateServiceTest에서 병합 적용 흐름을 검증하도록 보강한 작업이다. 입력, 처리, 결과 흐름을 확인했고 동선 관련 잔여 문제 없이 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:22:00', '2026-05-18 18:22:00'),
  (2004, 204, 201, '[API] 삭제 태그 조회 제외 보정', 'API 작업 진행 중 유사도 이슈가 남지 않도록 삭제 태그 조회 제외 보정 범위를 다시 확인하기로 했다.', '유사도 관점에서 조회 조건 보정 범위를 다시 나누고 필요한 확인 항목을 묶었다. 일부 흐름은 확인했지만 유사도 관련 케이스를 한 번 더 눌러 보는 중이다.', 'IN_PROGRESS', 'HIGH', 2.5, '2026-05-18', '2026-05-19', NULL, '삭제 태그 조회 제외 보정은 삭제 태그가 유사도 조회에 남지 않도록 조회 조건 범위를 다시 나눈 작업이다. 일부 흐름은 확인됐지만 유사도 관련 케이스를 추가로 눌러 보는 중이라 진행 중이다.', false, 'COMPLETED', false, '2026-05-18 10:33:00', '2026-05-18 18:33:00'),
  (2005, 205, 201, '[API] 업무일지 제목 추천 API 추가', '놓치지 않게 WorklogController 컨트롤러를 살펴보고 요청 파라미터와 응답 형태에 문제가 없는지 정리해 달라는 요청을 받았다.', '업무일지 제목 추천 API 추가 작업을 진행하며 WorklogController 컨트롤러의 입력, 처리, 결과가 한 흐름으로 이어지게 조정했다. 권한 관점에서 요청 파라미터와 응답 형태를 확인해 추가 조치 없이 마무리할 수 있는 상태로 봤다.', 'COMPLETED', 'LOW', 3.0, '2026-05-18', '2026-05-19', '2026-05-18', '업무일지 제목 추천 API 추가는 WorklogController의 입력과 응답 계약을 정리한 작업이다. 권한 관점의 요청 파라미터와 응답 형태 확인까지 마쳐 추가 조치 없이 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:44:00', '2026-05-18 18:44:00'),
  (2006, 206, 201, '[AI] 업무일지 제목 추천 API 추가', '운영 기준으로 worklog_polish_chain 서비스 로직을 살펴보고 변경 전후 흐름에 문제가 없는지 정리해 달라는 요청을 받았다.', '업무일지 제목 추천 API 추가 작업을 진행하며 worklog_polish_chain 서비스 로직의 입력, 처리, 결과가 한 흐름으로 이어지게 조정했다. 변경 전후 흐름은 아직 추가 확인이 필요해 다음 작업에서 배포부터 이어볼 예정이다.', 'PENDING', 'NORMAL', 1.0, '2026-05-18', '2026-05-20', NULL, '업무일지 제목 추천 API 추가는 AI 영역의 worklog_polish_chain 처리 흐름을 제목 추천에 맞게 연결한 작업이다. 입력, 처리, 결과 흐름은 정리했지만 변경 전후 확인이 남아 배포 단계부터 이어갈 예정이다.', false, 'COMPLETED', false, '2026-05-18 10:55:00', '2026-05-18 18:55:00'),
  (2007, 201, 201, '[API] 업무 등록 후 Light 인덱스 요청 추가', '업무 등록 후 Light 인덱스 요청 추가 건은 후처리 흐름이 중간에 끊기지 않도록 TriggerWorklogLightIndexDto 서비스 로직부터 점검해 달라는 요청이 있었다.', '놓치지 않게 TriggerWorklogLightIndexDto 서비스 로직을 확인하면서 업무 등록 후 Light 인덱스 요청 추가 처리 순서와 예외 상황을 함께 정돈했다. 요청 파라미터와 응답 형태를 확인한 뒤 QA에서 다시 볼 항목만 따로 남겼다.', 'COMPLETED', 'HIGH', 1.5, '2026-05-18', '2026-05-19', '2026-05-18', '업무 등록 후 Light 인덱스 요청 추가는 TriggerWorklogLightIndexDto 기반 후처리 순서를 정돈한 작업이다. 예외 상황과 응답 형태를 함께 확인했고 QA 재확인 항목만 남긴 상태로 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:06:00', '2026-05-18 18:06:00'),
  (2008, 202, 201, '[API] 업무 AI 후처리 통합 흐름 정리', 'FileService 서비스 로직 개선 결과가 실제 업무 흐름에 맞는지 재현 관점으로 확인하기로 했다.', 'API 영역의 FileService 서비스 로직을 살펴 업무 AI 후처리 통합 흐름 정리 작업에 맞게 개선 범위를 정리했다. 재현 관점에서 요청 파라미터와 응답 형태를 확인해 추가 조치 없이 마무리할 수 있는 상태로 봤다.', 'COMPLETED', 'NORMAL', 2.0, '2026-05-18', '2026-05-19', '2026-05-18', '업무 AI 후처리 통합 흐름 정리는 FileService 개선 범위를 실제 업무 흐름에 맞게 정리한 작업이다. 재현 관점에서 요청 파라미터와 응답 형태를 확인해 추가 조치 없이 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:17:00', '2026-05-18 18:17:00'),
  (2009, 203, 201, '[API] 업무 AI 후처리 통합 흐름 검증 추가', 'API 영역의 업무 AI 후처리 통합 흐름 검증 추가 작업에서 FileServiceTest 서비스 로직까지 같이 봐 달라는 요청을 받았다.', 'FileServiceTest 서비스 로직에서 업무 AI 후처리 통합 흐름 검증 추가에 필요한 추가 작업을 처리하고, 후처리 흐름이 중간에 끊기지 않도록 흐름을 맞췄다. 요청 파라미터와 응답 형태를 확인한 뒤 QA에서 다시 볼 항목만 따로 남겼다.', 'COMPLETED', 'NORMAL', 2.5, '2026-05-18', '2026-05-19', '2026-05-18', '업무 AI 후처리 통합 흐름 검증 추가는 FileServiceTest에서 후처리 흐름 단절 여부를 검증하도록 보강한 작업이다. 요청 파라미터와 응답 형태 확인 후 QA 확인 항목만 남기고 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:28:00', '2026-05-18 18:28:00'),
  (2010, 204, 201, '[API] worklog AI dispatch 상태 전이 추가', 'API 담당자와 맞춰 보며 Worklog 서비스 로직 추가 이후 남는 확인 항목을 정리하기로 했다.', '예시를 두고 Worklog 서비스 로직을 확인하면서 worklog AI dispatch 상태 전이 추가 처리 순서와 예외 상황을 함께 정돈했다. 일부 흐름은 확인했지만 AI 관련 케이스를 한 번 더 눌러 보는 중이다.', 'IN_PROGRESS', 'HIGH', 3.0, '2026-05-18', '2026-05-19', NULL, 'worklog AI dispatch 상태 전이 추가는 Worklog 서비스 로직에서 AI 후처리 상태 전이 순서를 정리한 작업이다. 예외 상황 일부는 확인됐지만 AI 관련 케이스를 한 번 더 확인 중이라 진행 중이다.', false, 'COMPLETED', false, '2026-05-18 10:39:00', '2026-05-18 18:39:00'),
  (2011, 205, 201, '[API] worklog AI 상태 전이 검증 추가', 'WorklogAiPostProcessServiceTest 서비스 로직 변경 후 사용자가 겪는 흐름이 자연스러운지 확인하고 필요한 후속 조치를 적어 달라는 요청이 있었다.', 'WorklogAiPostProcessServiceTest 서비스 로직에서 worklog AI 상태 전이 검증 추가에 필요한 추가 작업을 처리하고, 후처리 흐름이 중간에 끊기지 않도록 흐름을 맞췄다. 요청 파라미터와 응답 형태를 확인한 뒤 QA에서 다시 볼 항목만 따로 남겼다.', 'COMPLETED', 'LOW', 1.0, '2026-05-18', '2026-05-19', '2026-05-18', 'worklog AI 상태 전이 검증 추가는 WorklogAiPostProcessServiceTest에서 후처리 상태 전이를 검증하도록 보강한 작업이다. 후처리 흐름과 요청 응답 형태를 확인했고 QA 재확인 항목만 남긴 상태로 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:40:00', '2026-05-18 18:40:00'),
  (2012, 206, 201, '[INFRA] worklog AI 파이프라인 환경 변수 추가', 'INFRA 담당자와 맞춰 보며 배포 환경 설정 추가 이후 남는 확인 항목을 정리하기로 했다.', '환경 차이를 보며 배포 환경 설정을 확인하면서 worklog AI 파이프라인 환경 변수 추가 처리 순서와 예외 상황을 함께 정돈했다. 환경 변수와 배포 절차는 아직 추가 확인이 필요해 다음 작업에서 환경부터 이어볼 예정이다.', 'PENDING', 'NORMAL', 1.5, '2026-05-18', '2026-05-20', NULL, 'worklog AI 파이프라인 환경 변수 추가는 배포 환경 설정에서 AI 파이프라인 실행 조건을 맞춘 작업이다. 환경 변수와 배포 절차 확인이 더 필요해 다음 작업에서 환경 점검부터 이어갈 예정이다.', false, 'COMPLETED', false, '2026-05-18 10:51:00', '2026-05-18 18:51:00'),
  (2013, 201, 201, '[API] 기존 hybrid 업무 검색 구현 제거', 'InternalSemanticWorklogSearchApiDto 서비스 로직 변경 후 사용자가 겪는 흐름이 자연스러운지 확인하고 필요한 후속 조치를 적어 달라는 요청이 있었다.', 'InternalSemanticWorklogSearchApiDto 서비스 로직에서 기존 hybrid 업무 검색 구현 제거에 필요한 추가 작업을 처리하고, 후처리 흐름이 중간에 끊기지 않도록 흐름을 맞췄다. 요청 파라미터와 응답 형태를 다시 확인했고, 일정 관련 남은 문제는 따로 발견되지 않았다.', 'COMPLETED', 'HIGH', 2.0, '2026-05-18', '2026-05-19', '2026-05-18', '기존 hybrid 업무 검색 구현 제거는 InternalSemanticWorklogSearchApiDto 흐름에서 기존 검색 구현을 정리한 작업이다. 후처리 흐름과 요청 응답 형태를 확인했고 일정 관련 잔여 문제 없이 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:02:00', '2026-05-18 18:02:00'),
  (2014, 202, 201, '[API] LightRAG 업무 검색 client 추가', 'API 영역의 LightRAG 업무 검색 client 추가 작업에서 요청·응답 구조까지 같이 봐 달라는 요청을 받았다.', '요청·응답 구조에서 LightRAG 업무 검색 client 추가에 필요한 추가 작업을 처리하고, 요청과 응답이 같은 흐름으로 처리되도록 흐름을 맞췄다. 영향 관점에서 요청 파라미터와 응답 형태를 확인해 추가 조치 없이 마무리할 수 있는 상태로 봤다.', 'COMPLETED', 'NORMAL', 2.5, '2026-05-18', '2026-05-19', '2026-05-18', 'LightRAG 업무 검색 client 추가는 LightRAG 연동을 위한 요청·응답 구조를 API 흐름에 연결한 작업이다. 영향 관점의 파라미터와 응답 형태를 확인해 추가 조치 없이 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:13:00', '2026-05-18 18:13:00'),
  (2015, 203, 201, '[API] LightRAG 업무 시맨틱 검색 서비스 추가', 'SearchSemanticWorklogsApiDto 서비스 로직 추가 결과가 실제 업무 흐름에 맞는지 회귀 관점으로 확인하기로 했다.', 'API 영역의 SearchSemanticWorklogsApiDto 서비스 로직을 살펴 LightRAG 업무 시맨틱 검색 서비스 추가 작업에 맞게 추가 범위를 정리했다. 요청 파라미터와 응답 형태를 다시 확인했고, 회귀 관련 남은 문제는 따로 발견되지 않았다.', 'COMPLETED', 'NORMAL', 3.0, '2026-05-18', '2026-05-19', '2026-05-18', 'LightRAG 업무 시맨틱 검색 서비스 추가는 SearchSemanticWorklogsApiDto 기반 검색 서비스 범위를 추가한 작업이다. 회귀 관점에서 요청 파라미터와 응답 형태를 재확인했고 남은 문제 없이 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:24:00', '2026-05-18 18:24:00'),
  (2016, 204, 201, '[API] 업무 검색 endpoint 분리', 'WorklogController 컨트롤러 변경 후 사용자가 겪는 흐름이 자연스러운지 확인하고 필요한 후속 조치를 적어 달라는 요청이 있었다.', 'WorklogController 컨트롤러에서 업무 검색 endpoint 분리에 필요한 개선 작업을 처리하고, 요청과 응답이 같은 흐름으로 처리되도록 흐름을 맞췄다. 현재는 요청 파라미터와 응답 형태를 확인했고, AI 관점의 마지막 점검이 남아 있다.', 'IN_PROGRESS', 'HIGH', 1.0, '2026-05-18', '2026-05-19', NULL, '업무 검색 endpoint 분리는 WorklogController에서 검색 요청과 응답 흐름을 분리해 맞춘 작업이다. 기본 요청 응답 형태는 확인했지만 AI 관점의 마지막 점검이 남아 진행 중이다.', false, 'COMPLETED', false, '2026-05-18 10:35:00', '2026-05-18 18:35:00'),
  (2017, 205, 201, '[API] 부서장 업무 검색 범위 보정', '부서장 업무 검색 범위 보정은 알림 판단이 필요한 건이라 요청 파라미터와 응답 형태까지 같이 확인해 달라는 요청이 있었다.', 'API 영역의 조회 조건을 살펴 부서장 업무 검색 범위 보정 작업에 맞게 보정 범위를 정리했다. 요청 파라미터와 응답 형태를 확인한 뒤 QA에서 다시 볼 항목만 따로 남겼다.', 'COMPLETED', 'LOW', 1.5, '2026-05-18', '2026-05-19', '2026-05-18', '부서장 업무 검색 범위 보정은 부서장 권한에서 조회 조건과 알림 판단 범위를 맞춘 작업이다. 요청 파라미터와 응답 형태 확인을 마쳤고 QA 재확인 항목만 남긴 상태로 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:46:00', '2026-05-18 18:46:00'),
  (2018, 206, 201, '[AI] 태그 병합 후보 생성 조건 보강', 'tag_merge_model 서비스 로직 반영 결과가 실제 업무 흐름에 맞는지 환경 관점으로 확인하기로 했다.', 'AI 영역의 tag_merge_model 서비스 로직을 살펴 태그 병합 후보 생성 조건 보강 작업에 맞게 반영 범위를 정리했다. 환경 판단에 필요한 변경 전후 흐름을 더 모아야 해서 완료 처리는 보류했다.', 'PENDING', 'NORMAL', 2.0, '2026-05-18', '2026-05-20', NULL, '태그 병합 후보 생성 조건 보강은 tag_merge_model의 후보 생성 조건을 실제 업무 흐름에 맞게 반영한 작업이다. 환경 판단에 필요한 변경 전후 흐름을 더 모아야 해 완료 처리는 보류됐다.', false, 'COMPLETED', false, '2026-05-18 10:57:00', '2026-05-18 18:57:00'),
  (2019, 201, 201, '[API] 태그 병합 후보 수정 및 병합 API 추가', '태그 병합 후보 수정 및 병합 API 추가 건은 요청과 응답이 같은 흐름으로 처리되도록 TagMergeCandidateController 컨트롤러부터 점검해 달라는 요청이 있었다.', '같이 TagMergeCandidateController 컨트롤러를 확인하면서 태그 병합 후보 수정 및 병합 API 추가 처리 순서와 예외 상황을 함께 정돈했다. 요청 파라미터와 응답 형태를 다시 확인했고, 검토 관련 남은 문제는 따로 발견되지 않았다.', 'COMPLETED', 'HIGH', 2.5, '2026-05-18', '2026-05-19', '2026-05-18', '태그 병합 후보 수정 및 병합 API 추가는 TagMergeCandidateController에서 후보 수정과 병합 흐름을 연결한 작업이다. 요청과 응답 흐름을 재확인했고 검토 관련 잔여 문제 없이 완료됐다.', false, 'COMPLETED', false, '2026-05-18 10:08:00', '2026-05-18 18:08:00'),
